    "Vinasat 1": { orbit: "GEO", status: "active", platform: "A2100A", operator: "Vietnam Posts and Telecommunications Group (VNPT)", vehicle: "Ariane 5 ECA", mass: "2637", launchDate: "18-Apr-2008", lifetime: "15 yrs.", comments: "12 Ku-band, and 8 C-band transponders to provide voice, video, and Internet services to Vietnam, eastern Asia, India, Australia, Japan, and Hawaii", comments_zh: "12个Ku和8个C-band transponder，为越、东亚、印、澳、日及夏威夷提供服务。" },
