    "APSTAR 6E (MPSat 3)": { orbit: "GEO", status: "active", platform: "DFH-3E Bus", operator: "APT Satellite Holdings Ltd.", vehicle: "Long March CZ-2C", mass: "4300", launchDate: "13-Jan-2023", lifetime: "15+ yrs.", comments: "This all-electric propulsion communications satellite contains twenty-five (25) Ku-band user beams and three (3) Ka-band gateway beams on board with a 30Gbps payload capacity. Focusing on the customized payload market in South East Asia, the APSTAR-6E satellite will provide cost effective high throughput communication services.", comments_zh: "全电推通信卫星，具25个Ku用户波束及3个Ka网关波束，总容量30 Gbps。聚焦东南亚市场。" },
