    "Express AT2": { orbit: "GEO", status: "active", platform: "Express-1000K", operator: "Russian Satellite Communications Company", vehicle: "Proton M", mass: "1427", launchDate: "16-Mar-2014", lifetime: "15 yrs.", comments: "16 Ku-band transponders to cover eastern part of Russia", comments_zh: "16个Ku-band transponder，覆盖俄罗斯东部。" },
