    "XM 3 (XM Rhythm)": { orbit: "GEO", status: "active", platform: "BSS-702", operator: "XM Satellite Radio Holdings Inc./Sirius Satellite Radio", vehicle: "Zenit 3SL", mass: "4703", launchDate: "1-Mar-2005", lifetime: "15 yrs.", comments: "2 active X/S-band transponders, each with 16 active (6 spare) 228-w TWTAs to provide state-of-the-art digital audio radio programming directly to cars, homes and portable radios coast to coast.", comments_zh: "2个X/S-band工作 transponder，为北美提供高质量数字音频广播。" },
    "Sirius XM8 (SXM-8)": { orbit: "GEO", status: "active", platform: "LS-1300", operator: "XM Satellite Radio Holdings Inc./Sirius Satellite Radio", vehicle: "Falcon 9 v1.2", mass: "7000", launchDate: "6-Jun-2021", lifetime: "15+ years", comments: "S-band capacity to provide entertainment and data services to tens of millions of subscribers across North America replacing XM-4.", comments_zh: "S-band容量，为北美千万用户提供娱乐和数据服务。替换XM-4。" },
    "Sirius XM9 (SXM9, SXM-9)": { orbit: "GEO", status: "active", platform: "LS-1300", operator: "XM Satellite Radio Holdings Inc./Sirius Satellite Radio", vehicle: "Falcon 9 v1.2", mass: "7000", launchDate: "5-Dec-2024", lifetime: "15+ years", comments: "Replacement satellite for failed XM7. S-Band transponders", comments_zh: "替换XM7故障星。具备S-Band transponder。" },
