    "Nuview Bravo (Anuvu Bravo, AstranisAero East)": { orbit: "GEO", status: "active", platform: "MicroGEO", operator: "Astranis Space Technologies Corp.", vehicle: "Falcon 9 v1.2", mass: "400", launchDate: "29-Dec-2024", lifetime: "7-10 years", comments: "8 Ku-band HTS spot beams to provide high-performance connectivity over North America and the Caribbean", comments_zh: "8个Ku-band HTS spot beam，为北美及加勒比提供高性能连接。" },
    "Nimiq 4": { orbit: "GEO", status: "active", platform: "Eurostar-3000S", operator: "Telesat Canada Ltd.", vehicle: "Proton M", mass: "4850", launchDate: "20-Sep-2008", lifetime: "15 yrs.", comments: "32 active high-power transponders Ku-band and 8 Ka-band transponders to provide digital HDTV to Canada and America. Fully leased to Bell TV.", comments_zh: "32个高功率Ku及8个Ka-band transponder，向加、美提供数字高清电视。由Bell TV全周期租赁。" },
